const eur=new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0});
fetch('../submission.json').then(r=>r.json()).then(d=>{const material=d.decisions.filter(x=>x.reviewTier==='material_judgment');const operational=d.decisions.filter(x=>x.reviewTier==='operational');const s=d.statements.balanceSheet;const checks=[['Exactly 100 decisions',d.decisions.length===100,`${d.decisions.length} recorded`],['75 operational decisions',operational.length===75,`${operational.length} recorded`],['25 material judgments',material.length===25,`${material.length} recorded`],['Material judgments have AI trail',material.every(x=>x.aiProposal&&x.independentChallenge&&x.studentReasoning),`${material.filter(x=>x.aiProposal&&x.independentChallenge&&x.studentReasoning).length}/25 complete`],['Student certification present',d.studentCertification.materialJudgmentsApproved===true,`${d.student.name} · ${d.student.id}`],['Balance sheet balances',s.totalAssets===s.totalLiabilitiesAndEquity,`${eur.format(s.totalAssets)} = ${eur.format(s.totalLiabilitiesAndEquity)}`],['Cash flow reconciles',d.statements.cashFlow.openingCash+d.statements.cashFlow.netDecrease===d.statements.cashFlow.closingCash,`${eur.format(d.statements.cashFlow.closingCash)} closing cash`],['Equity reconciles',d.schedules.equity.opening+d.schedules.equity.profit-d.schedules.equity.ownerDistributions===d.schedules.equity.closing,`${eur.format(d.schedules.equity.closing)} closing equity`]];document.getElementById('review').innerHTML=`<div class="summary-grid"><div class="metric"><p>Checks passed</p><strong>${checks.filter(x=>x[1]).length}/${checks.length}</strong></div><div class="metric"><p>Evidence basis</p><strong>Primary</strong></div><div class="metric"><p>Reported profit</p><strong>${eur.format(d.statements.profitAndLoss.profitForPeriod)}</strong></div><div class="metric"><p>Status</p><strong>Ready</strong></div></div><article class="card"><div class="card-header"><h2>Control results</h2><p>Structural, certification and core reconciliation tests.</p></div><div class="table-wrap"><table><tbody>${checks.map(x=>`<tr><td>${x[0]}</td><td>${x[2]}</td><td class="${x[1]?'positive':'negative'}">${x[1]?'Pass':'Check'}</td></tr>`).join('')}</tbody></table></div></article><article class="method-note"><h2>Review boundary</h2><p>Course-feedback material and other student submissions are quality-control references only. They do not replace original case evidence. The insurance alternative is disclosed but not used in the primary evidence-only statements.</p></article>`;});
